class Array;def in_groups_of(number,fill_with=nil,&block)if number.to_i<=0;raise ArgumentError,"Group size must be a positive integer, was #{number.inspect}";end;if fill_with==false;collection=self;else padding=(number-size%number)%number;collection=dup.concat(Array.new(padding,fill_with));end;if block_given?;collection.each_slice(number,&block);else collection.each_slice(number).to_a;end;end;def in_groups(number,fill_with=nil,&block)division=size.div number;modulo=size%number;groups=[];start=0;number.times do |index|length=division+(modulo>0&&modulo>index ? 1: 0);groups<<last_group=slice(start,length);last_group<<fill_with if fill_with!=false&&modulo>0&&length==division;start+=length;end;if block_given?;groups.each(&block);else groups;end;end;def split(value=nil,&block)arr=dup;result=[];if block_given?;while(idx=arr.index(&block));result<<arr.shift(idx);arr.shift;end;else while(idx=arr.index(value));result<<arr.shift(idx);arr.shift;end;end;result<<arr;end;end
